const scenarios = [
  { key: 'preview running', hasModel: false, status: 'drafting', expected: 'wait_on_saved_id' },
  { key: 'awaiting approval', hasModel: false, status: 'preview_ready', expected: 'request_review' },
  { key: 'deadline exceeded', hasModel: false, status: 'rendering', expired: true, expected: 'save_for_reconciliation' },
  { key: 'ready without file', hasModel: false, status: 'ready', expected: 'save_for_reconciliation' },
  { key: 'ready with file', hasModel: true, status: 'ready', expected: 'eligible_for_download' },
  { key: 'job failed', hasModel: false, status: 'failed', expected: 'stop_attempt' },
];
function nextStep(result) {
  if (result.expired) return 'save_for_reconciliation';
  if (result.status === 'failed') return 'stop_attempt';
  if (result.status === 'preview_ready') return 'request_review';
  if (result.status === 'drafting' || result.status === 'rendering') return 'wait_on_saved_id';
  if (result.status === 'ready' && result.hasModel === true) return 'eligible_for_download';
  return 'save_for_reconciliation';
}
return scenarios.map(test => {
  const observed = nextStep(test);
  if (observed !== test.expected) throw new Error('Unexpected branch: ' + test.key);
  return { json: { scenario: test.key, result: observed } };
});
